<?php
declare(strict_types=1);
namespace App;
final class RoleController {
    public static function index():string {RoleService::admin();$q=trim((string)($_GET['q']??''));$s=str_replace('<div class="page-head-actions"></div>','<div class="page-head-actions"><button class="btn btn-primary" type="button" data-open-form="/settings/roles/new">Создать роль</button></div>',View::heading('Роли','','users-group'));$s.='<section class="table-card registry-ui-card registry-ui-sticky-table registry-ui-sticky-table--wide-scroll registry-ui-scroll" data-registry-id="system-roles" data-registry-view><div class="table-toolbar registry-ui-toolbar ui-detail-card"><span class="found-label">Ролей: <b data-result-count>';
        $query=DB::pdo()->prepare('SELECT r.*,COUNT(u.id) user_count FROM roles r LEFT JOIN users u ON u.role=r.id WHERE r.name LIKE ? OR r.description LIKE ? GROUP BY r.id ORDER BY r.id');$query->execute(['%'.$q.'%','%'.$q.'%']);$rows=$query->fetchAll();$s.=count($rows).'</b></span><form class="toolbar-right" method="get" data-search-form><input class="registry-ui-search" type="search" name="q" value="'.View::e($q).'" placeholder="Поиск по таблице" aria-label="Поиск по таблице" data-live-search></form></div><div class="table-scroll" role="region" aria-label="Роли: прокрутка таблицы" tabindex="0"><table class="table registry-ui-table registry-ui-data registry-ui-data--columns"><thead><tr><th class="registry-ui-id" scope="col">ID</th><th scope="col">Роль</th><th scope="col">Описание</th><th scope="col">Пользователей</th><th scope="col">Доступ</th></tr></thead><tbody>';foreach($rows as $r)$s.='<tr tabindex="0" data-record-key="'.View::e($r['id']).'" data-record-url="/settings/roles/edit?id='.rawurlencode($r['id']).'" aria-label="Открыть '.View::e($r['name']).'"><td class="registry-ui-id">'.View::e($r['id']).'</td><td><span class="registry-ui-name">'.View::e($r['name']).'</span></td><td>'.View::e($r['description']).'</td><td>'.$r['user_count'].'</td><td><span class="badge '.($r['id']==='admin'?'badge-ok':'badge-neutral').'">'.($r['id']==='admin'?'Полный доступ':'По матрице прав').'</span></td></tr>';$s.='</tbody></table></div><div data-pagination></div></section><section class="panel-section ui-detail-card"><p class="registry-ui-secondary">Обычные роли получают права «нет доступа», «чтение» или «чтение и редактирование». Управление пользователями и ролями доступно Администратору.</p></section>';return View::page('Роли',$s);}
    public static function edit(bool $new=false):string {
        RoleService::admin();$id=$new?null:(string)($_GET['id']??'');$role=$id?RoleService::role($id):['id'=>null,'name'=>'','description'=>'','revision'=>1,'grants_configured'=>1,'workflow_kind'=>null];$error='';
        if($_SERVER['REQUEST_METHOD']==='POST'){Http::checkCsrf();try{RoleService::save($id,$_POST);Http::redirect('/settings/roles');}catch(\RuntimeException $e){if(!in_array($e->getCode(),[409,422],true))throw $e;http_response_code(200);$error='<div class="form-alert alert-error" role="alert"><span class="alert-mark" aria-hidden="true">×</span><div class="alert-body"><div class="alert-body-title">'.View::e($e->getMessage()).'</div></div></div>';}}
        $title=$id?'Изменить роль':'Создать роль';$grants=RoleService::grants($role);$fragment='<div data-editor-fragment data-editor-title="'.$title.'"><form method="post" action="'.($new?'/settings/roles/new':'/settings/roles/edit?id='.rawurlencode($id)).'" id="role-form" class="registry-ui-modal-grid"><input type="hidden" name="_csrf" value="'.View::e(Http::csrf()).'"><input type="hidden" name="expected_revision" value="'.View::e($_POST['expected_revision']??$role['revision']).'">'.$error.'<div class="registry-ui-modal-grid"><div class="field"><label class="field-label" for="role-name">Название роли</label><input class="field-input" id="role-name" name="name" value="'.View::e($_POST['name']??$role['name']).'" maxlength="100" required'.($id==='admin'?' disabled':'').'></div><div class="field"><label class="field-label" for="role-description">Описание</label><textarea class="field-textarea" id="role-description" name="description" rows="3">'.View::e($_POST['description']??$role['description']).'</textarea></div></div>';
        if($id==='admin')$fragment.='<span class="registry-ui-modal-help">Администратору доступны все настройки и страницы.</span>';else{$fragment.='<span class="registry-ui-modal-summary">Права на страницы</span>';foreach(PagePolicy::catalog()as $key=>$page){$value=$_POST['grants'][$key]??$grants[$key]??0;$fragment.='<div class="field"><label class="field-label" for="grant-'.View::e($key).'">'.View::e($page['module'].' · '.$page['title']).'</label><select class="field-select" name="grants['.View::e($key).']" id="grant-'.View::e($key).'">';foreach([0=>'Нет доступа',1=>'Чтение',2=>'Чтение и редактирование']as $level=>$label)$fragment.='<option value="'.$level.'"'.((int)$value===$level?' selected':'').'>'.$label.'</option>';$fragment.='</select></div>';}$fragment.='<span class="registry-ui-modal-help">Новые страницы закрыты по умолчанию.</span>';}$fragment.='</form>';
        if($id&&$id!=='admin')$fragment.='<form id="role-delete-form" method="post" action="/settings/roles/delete" data-confirm="Удалить роль? Она должна быть не назначена пользователям." hidden><input type="hidden" name="_csrf" value="'.View::e(Http::csrf()).'"><input type="hidden" name="id" value="'.View::e($id).'"><input type="hidden" name="revision" value="'.$role['revision'].'"></form>';$fragment.='<div class="modal-foot-actions" data-editor-actions><button class="btn btn-secondary" type="button" data-editor-close>Отмена</button>'.($id&&$id!=='admin'?'<button class="btn btn-secondary" type="submit" form="role-delete-form">Удалить роль</button>':'').'<button class="btn btn-primary" type="submit" form="role-form">Сохранить</button></div></div>';
        if(($_SERVER['HTTP_X_REQUESTED_WITH']??'')==='ERP-Fetch')return $fragment;return self::fullPage($role,$grants,$error,$new);
    }
    private static function fullPage(array $role,array $grants,string $error,bool $new):string {
        $id=$role['id'];$title=$id?'Изменить роль':'Создать роль';$heading=View::heading($title,'','users-group');$heading=str_replace('<div class="page-head-actions"></div>','<div class="page-head-actions"><a class="btn btn-secondary" href="/settings/roles">Отмена</a><button class="btn btn-primary" type="submit" form="role-form">Сохранить роль и права</button></div>',$heading);$s='<form method="post" class="demo-stack" id="role-form"><input type="hidden" name="_csrf" value="'.View::e(Http::csrf()).'"><input type="hidden" name="expected_revision" value="'.View::e($_POST['expected_revision']??$role['revision']).'"><section class="table-card registry-ui-card demo-form-width"><div class="table-toolbar registry-ui-toolbar"><span class="found-label">Сведения о роли</span>'.($id==='admin'?'<span class="badge badge-ok">Системная роль</span>':'').'</div><section class="panel-section"><div class="form-grid-2">'.$error.'<div class="field"><label class="field-label" for="role-name">Название роли</label><input class="field-input" name="name" id="role-name" maxlength="100" value="'.View::e($_POST['name']??$role['name']).'" required'.($id==='admin'?' disabled':'').'></div><div class="field"><label class="field-label" for="role-description">Описание</label><textarea class="field-textarea" name="description" id="role-description" rows="3">'.View::e($_POST['description']??$role['description']).'</textarea></div></div></section></section><section class="table-card registry-ui-card"><div class="table-toolbar registry-ui-toolbar"><span class="found-label">Права на страницы</span><span class="registry-ui-secondary">Новые страницы закрыты по умолчанию</span></div>';
        if($id==='admin')$s.='<section class="panel-section"><p class="registry-ui-primary">Администратор имеет полный доступ к пользователям, ролям и включённым страницам.</p></section>';else{$s.='<div class="table-scroll"><table class="table registry-ui-table registry-ui-data registry-ui-data--columns"><thead><tr><th scope="col">Раздел</th><th scope="col">Страница</th><th scope="col">Уровень доступа</th></tr></thead><tbody>';foreach(PagePolicy::catalog()as $key=>$page){$value=$_POST['grants'][$key]??$grants[$key]??0;$s.='<tr><td>'.View::e($page['module']).'</td><td><label class="registry-ui-name" for="grant-'.View::e($key).'">'.View::e($page['title']).'</label></td><td><select class="field-select" name="grants['.View::e($key).']" id="grant-'.View::e($key).'">';foreach([0=>'Нет доступа',1=>'Чтение',2=>'Чтение и редактирование']as $level=>$label)$s.='<option value="'.$level.'"'.((int)$value===$level?' selected':'').'>'.$label.'</option>';$s.='</select></td></tr>';}$s.='</tbody></table></div><section class="panel-section"><p class="registry-ui-secondary">Свой профиль всегда доступен для просмотра. Управление пользователями и ролями доступно только Администратору.</p></section>';}$s.='</section></form>';
        if($id&&$id!=='admin')$s.='<section class="panel-section"><form method="post" action="/settings/roles/delete" data-confirm="Удалить эту роль? Удаление возможно, только если роль не назначена пользователям."><input type="hidden" name="_csrf" value="'.View::e(Http::csrf()).'"><input type="hidden" name="id" value="'.View::e($id).'"><input type="hidden" name="revision" value="'.$role['revision'].'"><button class="btn btn-secondary" type="submit">Удалить неиспользуемую роль</button></form></section>';return View::page($title,$heading.$s);
    }
    public static function delete():never {RoleService::admin();if($_SERVER['REQUEST_METHOD']!=='POST')throw new \RuntimeException('Требуется POST',405);Http::checkCsrf();RoleService::delete((string)($_POST['id']??''),(int)($_POST['revision']??0));Http::redirect('/settings/roles');}
}
